import {useEffect,useRef,useState,type RefObject} from 'react'
import type {HostedWorkspaceActor} from '@/lib/workspace-api'
import {M77_LIMITATIONS,M77_SOURCE_PROFILE,M77_POPULATION_PROFILE,type M77Register,type M77SourceActivity,type M77PopulationDeclaration,type M77Version,type M77Report,type M77ReviewInput} from '../../../../packages/neuvetra-database/src/m77-contract'
import {m77CanonicalJson,validateM77SourceSave,validateM77PopulationSave} from '../../../../packages/neuvetra-database/src/m77-validation'
import {fugitiveRegisterRequest,fugitiveSaveRequest,fugitiveReviewRequest,fugitiveReportRequest,fugitiveReportDownload,fugitiveSnapshotDownload,fugitiveStatementDownload} from '@/lib/m77-api'
import {FugitiveSourceEditor} from './FugitiveSourceEditor'
import {FugitivePopulationEditor} from './FugitivePopulationEditor'
import {blankPopulation} from '@/lib/m77-form'

type Props={actor:HostedWorkspaceActor;workspaceId:string|null;headingRef:RefObject<HTMLHeadingElement|null>}
export function FugitiveWorkpapers(props:Props){
  const [identity,setIdentity]=useState({actor:props.actor,company:props.workspaceId,generation:0})
  if(identity.actor!==props.actor||identity.company!==props.workspaceId){setIdentity({actor:props.actor,company:props.workspaceId,generation:identity.generation+1});return null}
  return <FugitiveWorkspace key={identity.generation} {...props}/>
}
function FugitiveWorkspace({actor,workspaceId,headingRef}:Props){
  const [register,setRegister]=useState<M77Register|null>(null),[mode,setMode]=useState<'source'|'population'>('population'),[streamId,setStreamId]=useState(''),[versionId,setVersionId]=useState('')
  const [source,setSource]=useState<M77SourceActivity|null>(null),[declaration,setDeclaration]=useState<M77PopulationDeclaration>(blankPopulation),[editing,setEditing]=useState(false),[reason,setReason]=useState('')
  const [busy,setBusy]=useState(true),[message,setMessage]=useState('Loading fugitive-source records…'),[error,setError]=useState(false),[reviewNote,setReviewNote]=useState(''),[ack,setAck]=useState(false)
  const [decision,setDecision]=useState<'accept'|'changes'>('changes'),[openReport,setOpenReport]=useState<string|null>(null)
  const active=useRef(true),lock=useRef(false),attempt=useRef<{signature:string;key:string}|null>(null)
  const valid=()=>active.current&&!actor.signal?.aborted
  const manager=actor.role!=='member'
  const worksheet=register?.worksheets.find(w=>w.worksheetId===streamId)
  const versions=mode==='source'?worksheet?.versions??[]:register?.population.versions??[]
  const latest=versions[versions.length-1],selected=versions.find(v=>v.id===versionId)??latest
  const reports=mode==='source'?worksheet?.reports??[]:register?.population.reports??[]
  const reset=()=>{setEditing(false);setSource(null);setReason('');setReviewNote('');setAck(false);setDecision('changes');setOpenReport(null)}
  async function load(preferred?:M77Version){if(!workspaceId)return;const r=await fugitiveRegisterRequest(actor,workspaceId);if(valid()){setRegister(r);if(preferred){setMode(preferred.family);setStreamId(preferred.streamId);setVersionId(preferred.id)}reset()}}
  // eslint-disable-next-line react-hooks/exhaustive-deps -- The wrapper remounts this state on every actor/company identity change.
  useEffect(()=>{active.current=true;void(async()=>{try{if(workspaceId){await load();if(valid())setMessage('Compare the physical equipment list with source workpapers. Unknown or unsupported equipment remains a gap.')}else setMessage('No company workspace is assigned.')}catch(e){if(valid()){setError(true);setMessage(e instanceof Error?e.message:'Records unavailable.')}}finally{if(valid())setBusy(false)}})();return()=>{active.current=false}},[]) // Actor/company changes remount this component.
  async function action(kind:string,payload:unknown,work:(key:string)=>Promise<void>){if(!valid()||lock.current)return;lock.current=true;setBusy(true);setError(false);setMessage('Verifying the requested operation…');const signature=m77CanonicalJson({kind,payload});if(attempt.current?.signature!==signature)attempt.current={signature,key:crypto.randomUUID()};try{await work(attempt.current.key);if(valid())attempt.current=null}catch(e){if(valid()){setError(true);setMessage(e instanceof Error?e.message:'The operation could not be verified. Refresh before continuing.')}}finally{if(valid()){lock.current=false;setBusy(false)}}}
  function changeMode(next:'source'|'population'){setMode(next);setStreamId('');setVersionId('');reset()}
  function start(){if(!manager||busy||!register)return;reset();setEditing(true);if(mode==='population')setDeclaration(structuredClone(register.population.versions[register.population.versions.length-1]?.activity.declaration??blankPopulation()));else if(latest?.family==='source'){const draft=structuredClone(latest.activity),current=register.sources.find(s=>s.binding.sourceId===draft.binding.sourceId);if(current)draft.binding=current.binding;setSource(draft)}setMessage('Unsaved draft using current corporate coverage where the source is still available. Check the source binding. Saving adds a version; previous records remain retained.')}
  function chooseSource(id:string){const choice=register?.sources.find(s=>s.binding.sourceId===id);if(!choice)return;setSource(v=>v?{...v,binding:choice.binding}:{profile:M77_SOURCE_PROFILE,binding:choice.binding,label:'',assetId:'',equipment:'unknown',gas:null,capacityKg:null,calculatorInput:null,evidenceStatements:[]})}
  async function save(){if(!register?.coverageVersion||!workspaceId)return;const predecessor={expectedVersionId:latest?.id??null,expectedVersionSha256:latest?.versionSha256??null,correctionReason:latest?reason:null};const input=mode==='source'&&source?{...source,...predecessor}:{profile:M77_POPULATION_PROFILE,coverageVersionId:register.coverageVersion.id,coverageVersionSha256:register.coverageVersion.versionSha256,declaration,expectedDependencySha256:register.reconciliation.dependencySha256,...predecessor};if(mode==='source'&&!source)return;
    try{const candidate={...input,idempotencyKey:crypto.randomUUID()};if(mode==='source')validateM77SourceSave(candidate);else validateM77PopulationSave(candidate)}catch(e){setError(true);setMessage(e instanceof Error?e.message:'Check required source and evidence fields. Nothing was saved.');return}
    await action('save',input,async key=>{const version=await fugitiveSaveRequest(actor,workspaceId,mode,latest?.streamId??null,{...input,idempotencyKey:key});await load(version);if(valid())setMessage('Version saved. Separate internal review remains required; corporate Scope 1 remains incomplete.')})
  }
  async function review(){if(!workspaceId||!register||!latest)return;const input:Omit<M77ReviewInput,'idempotencyKey'>={versionId:latest.id,expectedVersionSha256:latest.versionSha256,expectedDependencySha256:mode==='population'?register.reconciliation.dependencySha256:null,decision:decision==='changes'?'changes_requested':mode==='source'?'accepted_bounded_internal':'accepted_bounded_reconciliation',note:reviewNote,acknowledgedLimitations:ack?[...M77_LIMITATIONS]:[]};await action('review',input,async key=>{await fugitiveReviewRequest(actor,workspaceId,mode,latest.streamId,{...input,idempotencyKey:key});await load(latest);if(valid())setMessage('The separate review decision was saved for this exact version.')})}
  async function retainReport(){if(!workspaceId||!register||!selected)return;const capturedReview=mode==='source'||selected.review?.dependencies?.dependencySha256===register.reconciliation.dependencySha256?selected.review:null;const input={versionId:selected.id,expectedVersionSha256:selected.versionSha256,expectedDecisionId:capturedReview?.id??null,expectedDecisionSha256:capturedReview?.decisionSha256??null,expectedReconciliationSha256:mode==='population'?register.reconciliation.contentSha256:null};await action('report',input,async key=>{await fugitiveReportRequest(actor,workspaceId,mode,selected.streamId,{...input,idempotencyKey:key});await load(selected);if(valid())setMessage('Report retained with its captured evidence, decisions and limitations.')})}
  async function showReport(report:M77Report,download:boolean,json=false){if(!workspaceId)return;await action('download',{report:report.id,download,json},async()=>{const html=await (json?fugitiveSnapshotDownload:fugitiveReportDownload)(actor,workspaceId,report);if(!valid())return;if(download){const url=URL.createObjectURL(new Blob([html],{type:json?'application/json;charset=utf-8':'text/html;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=`fugitive-report-${report.id}.${json?'json':'html'}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}else setOpenReport(html);setMessage('Retained report verified and opened.')})}
  async function downloadStatement(v:M77Version,id:string){if(!workspaceId)return;await action('statement',{id},async()=>{const text=await fugitiveStatementDownload(actor,workspaceId,v,id);if(!valid())return;const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=`fugitive-evidence-${id}.txt`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);setMessage('Retained evidence statement verified and downloaded.')})}
  return <section className="worksheet stationary-workspace controlled-stationary"><h2 ref={headingRef} tabIndex={-1}>Refrigerants and fire suppression</h2><p>Candidate workpapers and physical-equipment coverage · synthetic demonstration · Scope 1 incomplete</p>
    <p role={error?'alert':'status'} aria-live="polite">{message}</p>
    <nav className="worksheet-nav" aria-label="Fugitive workpaper views"><button disabled={busy} aria-pressed={mode==='population'} onClick={()=>changeMode('population')}>Equipment reconciliation</button><button disabled={busy} aria-pressed={mode==='source'} onClick={()=>changeMode('source')}>Source workpapers</button><button disabled={busy} onClick={()=>void action('refresh',{},async()=>{await load();if(valid())setMessage('Current evidence and dependencies refreshed.')})}>Refresh records</button></nav>
    {register&&<><h3>Current coverage findings</h3><p>{register.reconciliation.assets.length} declared devices · {register.reconciliation.sourceIds.length} corporate fugitive sources · {register.worksheets.length} workpapers</p>{register.reconciliation.findings.length?<ul>{register.reconciliation.findings.map((f,i)=><li key={i}>{f.assetId?`${f.assetId}: `:''}{f.message}</li>)}</ul>:<p>The declared supported population reconciles. This is not complete corporate Scope 1 or external assurance.</p>}
      {mode==='source'&&<label>Saved source workpaper<select disabled={busy||editing} value={streamId} onChange={e=>{setStreamId(e.target.value);setVersionId('');reset()}}><option value="">New source workpaper</option>{register.worksheets.map(w=><option key={w.worksheetId} value={w.worksheetId}>{w.versions[w.versions.length-1]?.activity.label??w.assetId}</option>)}</select></label>}
      {versions.length>0&&<label>Saved version<select disabled={busy||editing} value={selected?.id??''} onChange={e=>{setVersionId(e.target.value);setOpenReport(null)}}>{versions.map(v=><option key={v.id} value={v.id}>Version {v.version} — {v.review?.decision.replace(/_/g,' ')??'unreviewed'}</option>)}</select></label>}
      {selected&&!editing&&<><h3>{selected.family==='source'?selected.activity.label:'Physical population'} · version {selected.version}</h3><p>{selected.review?.decision.replace(/_/g,' ')??'No review saved'} · {new Date(selected.createdAt).toLocaleString()}</p>{selected.findings.length>0&&<ul>{selected.findings.map((f,i)=><li key={i}>{f.message}</li>)}</ul>}{selected.family==='source'&&selected.calculation&&<><h3>{selected.calculation.kg_co2e_display} kg CO₂e</h3><p>{selected.calculation.estimated_emitted_kg} kg estimated {selected.calculation.gas} emissions · GWP {selected.calculation.gwp}</p><p>Candidate servicing-based estimate. Statement retention does not authenticate an original record.</p></>}</>}
      {manager&&!editing&&<button disabled={busy||!register.coverageVersion} onClick={start}>{latest?'Prepare correction of latest version':mode==='source'?'Prepare source workpaper':'Declare equipment population'}</button>}
      {editing&&<><fieldset disabled={busy}>{mode==='source'?<><label>Corporate fugitive source<select value={source?.binding.sourceId??''} onChange={e=>chooseSource(e.target.value)}><option value="">Select source</option>{register.sources.map(s=><option key={s.binding.sourceId} value={s.binding.sourceId}>{s.sourceLabel} — {s.facilityLabel}{s.eligible?'':' — unsupported boundary'}</option>)}</select></label>{source&&<FugitiveSourceEditor value={source} onChange={setSource} disabled={busy}/>}</>:<FugitivePopulationEditor value={declaration} register={register} onChange={setDeclaration} disabled={busy}/>}{latest&&<label>Why this version is being corrected<textarea value={reason} onChange={e=>setReason(e.target.value)}/></label>}<button onClick={()=>void save()} disabled={busy||mode==='source'&&!source}>Save new version</button><button onClick={reset}>Discard unsaved draft</button></fieldset></>}
      {manager&&latest&&!editing&&selected?.id===latest.id&&<fieldset disabled={busy}><legend>Separate internal review</legend><p>A manager who contributed to this workpaper cannot approve it. The server checks reviewer eligibility and current evidence.</p><label>Decision<select value={decision} onChange={e=>setDecision(e.target.value as 'accept'|'changes')}><option value="changes">Request changes</option><option value="accept">Accept this bounded workpaper</option></select></label><label>Review explanation<textarea value={reviewNote} onChange={e=>setReviewNote(e.target.value)}/></label><label className="stationary-check"><input type="checkbox" checked={ack} onChange={e=>setAck(e.target.checked)}/>I acknowledge the synthetic data, unreleased method, incomplete Scope 1 and corporate inventory, unresolved legal requirements, no emissions aggregation and no external assurance.</label><button disabled={!ack||!reviewNote.trim()} onClick={()=>void review()}>Save separate review</button></fieldset>}
      {selected&&!editing&&<><h3>Retained evidence statements</h3>{selected.statements.map(s=><div className="worksheet-report-actions" key={s.id}><span>{s.reference} — {s.issuer} </span><button disabled={busy} onClick={()=>void downloadStatement(selected,s.id)}>Download statement</button></div>)}<h3>Retained reports</h3>{manager&&<button disabled={busy} onClick={()=>void retainReport()}>Retain report for selected version</button>}{reports.filter(r=>r.versionId===selected.id).map(r=><div className="worksheet-report-actions" key={r.id}><span>Report · {new Date(r.createdAt).toLocaleString()} </span><button disabled={busy} onClick={()=>void showReport(r,false)}>Open report</button><button disabled={busy} onClick={()=>void showReport(r,true)}>Download HTML report</button><button disabled={busy} onClick={()=>void showReport(r,true,true)}>Download report data</button></div>)}</>}
    </>}
    {openReport&&<><button onClick={()=>setOpenReport(null)}>Close report</button><iframe title="Retained fugitive workpaper report" srcDoc={openReport} sandbox="allow-modals" style={{width:'100%',minHeight:'36rem',border:'1px solid #ccc'}}/></>}
  </section>
}
